describe('res', function(){
  describe('.send()', function(){
    it('should set body to ""', function(done){
      var app = express();

      app.use(function(req, res){
        res.send();
      });

      request(app)
      .get('/')
      .expect(200, '', done);
    })
  })

  describe('.send(null)', function(){
    it('should set body to ""', function(done){
      var app = express();

      app.use(function(req, res){
        res.send(null);
      });

      request(app)
      .get('/')
      .expect('Content-Length', '0')
      .expect(200, '', done);
    })
  })

  describe('.send(undefined)', function(){
    it('should set body to ""', function(done){
      var app = express();

      app.use(function(req, res){
        res.send(undefined);
      });

      request(app)
      .get('/')
      .expect(200, '', done);
    })
  })

  describe('.send(Number)', function(){
    it('should send as application/json', function(done){
      var app = express();

      app.use(function(req, res){
        res.send(1000);
      });

      request(app)
      .get('/')
      .expect('Content-Type', 'application/json; charset=utf-8')
      .expect(200, '1000', done)
    })
  })

  describe('.send(String)', function(){
    it('should send as html', function(done){
      var app = express();

      app.use(function(req, res){
        res.send('<p>hey</p>');
      });

      request(app)
      .get('/')
      .expect('Content-Type', 'text/html; charset=utf-8')
      .expect(200, '<p>hey</p>', done);
    })

    it('should set ETag', function (done) {
      var app = express();

      app.use(function (req, res) {
        var str = Array(1000).join('-');
        res.send(str);
      });

      request(app)
      .get('/')
      .expect('ETag', 'W/"3e7-qPnkJ3CVdVhFJQvUBfF10TmVA7g"')
      .expect(200, done);
    })

    it('should not override Content-Type', function(done){
      var app = express();

    .expect('ETag', 'W/"3e7-qPnkJ3CVdVhFJQvUBfF10TmVA7g"')
    .expect(200, done);
  })

  it('should not override Content-Type', function(done){
    var app = express();

    app.use(function(req, res){
      res.set('Content-Type', 'text/plain').send(Buffer.from('hey'))
    });

    request(app)
    .get('/')
    .expect('Content-Type', 'text/plain; charset=utf-8')
    .expect(200, 'hey', done);
  })

  it('should accept Uint8Array', function(done){
    var app = express();
    app.use(function(req, res){
      const encodedHey = new TextEncoder().encode("hey");
      res.set("Content-Type", "text/plain").send(encodedHey);
    })

    request(app)
      .get("/")
      .expect("Content-Type", "text/plain; charset=utf-8")
      .expect(200, "hey", done);
  })

  it('should not override ETag', function (done) {
    var app = express()

    app.use(function (req, res) {
      res.type('text/plain').set('ETag', '"foo"').send(Buffer.from('hey'))
    })

    request(app)
    .get('/')
    .expect('ETag', '"foo"')
