	if (!this.#options.signal || !(request instanceof globalThis.Request)) {
		return request;
	}

	return new globalThis.Request(request, {
		signal: this.#options.signal,
		referrer: request.referrer,
		referrerPolicy: request.referrerPolicy,
	});
}

